SELECT id,to_char(operation_date,'YYYY-MM-DD'),direction,amount_minor,currency,source_kind,coalesce(source_system,''),coalesce(source_company_id,''),coalesce(external_id,''),imported_at,category_id,counterparty_inn,counterparty_name,purpose,version,created_at,import_id FROM core_transactions WHERE company_id=$1 AND account_id=$2 AND ($3::date IS NULL OR operation_date >= $3) AND ($4::date IS NULL OR operation_date <= $4) AND ($5::text='' OR direction=$5) AND ($6::uuid IS NULL OR category_id=$6) AND ($7::date IS NULL OR (operation_date,id)<($7,$8)) ORDER BY operation_date DESC,id DESC LIMIT $9;
